package com.ginga.naviai.auth.exception;

import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.context.request.WebRequest;

import com.ginga.naviai.user.exception.UserNotFoundException;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@ControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Object> handleValidation(MethodArgumentNotValidException ex, WebRequest request) {
        List<Map<String,String>> errors = new ArrayList<>();
        for (FieldError f : ex.getBindingResult().getFieldErrors()) {
            Map<String,String> err = new HashMap<>();
            err.put("field", f.getField());
            err.put("message", f.getDefaultMessage());
            errors.add(err);
        }
        Map<String,Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.BAD_REQUEST.value());
        body.put("errors", errors);
        return new ResponseEntity<>(body, new HttpHeaders(), HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(DuplicateResourceException.class)
    public ResponseEntity<Object> handleDuplicate(DuplicateResourceException ex) {
        Map<String,Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.CONFLICT.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.CONFLICT);
    }

    @ExceptionHandler(InvalidCredentialsException.class)
    public ResponseEntity<Object> handleInvalidCredentials(InvalidCredentialsException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.UNAUTHORIZED.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(AccountNotEnabledException.class)
    public ResponseEntity<Object> handleAccountNotEnabled(AccountNotEnabledException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.FORBIDDEN.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(InvalidTokenException.class)
    public ResponseEntity<Object> handleInvalidToken(InvalidTokenException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.UNAUTHORIZED.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(TokenExpiredException.class)
    public ResponseEntity<Object> handleTokenExpired(TokenExpiredException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.UNAUTHORIZED.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(UserNotFoundException.class)
    public ResponseEntity<Object> handleUserNotFound(UserNotFoundException ex) {
        Map<String, Object> body = new HashMap<>();
        body.put("timestamp", Instant.now().toString());
        body.put("status", HttpStatus.NOT_FOUND.value());
        body.put("message", ex.getMessage());
        return new ResponseEntity<>(body, HttpStatus.NOT_FOUND);
    }
}

package com.ginga.naviai.auth.controller;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.ginga.naviai.auth.dto.LoginRequest;
import com.ginga.naviai.auth.dto.LoginResponse;
import com.ginga.naviai.auth.dto.RegisterRequest;
import com.ginga.naviai.auth.dto.UserResponse;
import com.ginga.naviai.auth.dto.RefreshRequest;
import com.ginga.naviai.auth.dto.TokenResponse;
import com.ginga.naviai.auth.dto.LogoutRequest;
import com.ginga.naviai.auth.exception.DuplicateResourceException;
import com.ginga.naviai.auth.exception.InvalidCredentialsException;
import com.ginga.naviai.auth.exception.InvalidTokenException;
import com.ginga.naviai.auth.service.AuthService;
import com.ginga.naviai.config.SecurityConfig;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.mock.mockito.MockBean;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.context.annotation.Import;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.when;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.eq;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.util.Optional;

@WebMvcTest(AuthController.class)
@AutoConfigureMockMvc(addFilters = true)
@Import(SecurityConfig.class)
public class AuthControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private AuthService authService;
    @MockBean
    private com.ginga.naviai.auth.service.ConfirmationTokenService confirmationTokenService;
    @MockBean
    private com.ginga.naviai.auth.repository.UserRepository userRepository;
    @MockBean
    private com.ginga.naviai.auth.service.TokenBlacklistService tokenBlacklistService;
    @MockBean
    private com.ginga.naviai.auth.filter.JwtAuthenticationFilter jwtAuthenticationFilter;

    @Autowired
    private ObjectMapper mapper;

    @Test
    void register_controller_success_returns201() throws Exception {
        // 有効な登録リクエストが HTTP 201 を返し、作成されたユーザーのフィールドがレスポンスに含まれることを検証する
        // Arrange: mock service to return response
        UserResponse ur = new UserResponse();
        ur.setId(10L);
        ur.setUsername("ctrlUser");
        ur.setEmail("ctrl@ginga.info");
        when(authService.register(any(RegisterRequest.class))).thenReturn(ur);

        RegisterRequest req = new RegisterRequest();
        req.setUsername("ctrlUser");
        req.setEmail("ctrl@ginga.info");
        req.setPassword("Aa1!aaaa");

        mockMvc.perform(post("/api/v1/auth/register")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.id").value(10L))
            .andExpect(jsonPath("$.username").value("ctrlUser"));
    }

    @Test
    void register_controller_validationError_returns400() throws Exception {
        // 無効なリクエスト（バリデーション失敗）が HTTP 400 を返すことを検証する
        // Arrange: invalid email domain
        RegisterRequest req = new RegisterRequest();
        req.setUsername("x");
        req.setEmail("bad@other.com");
        req.setPassword("weak");

        mockMvc.perform(post("/api/v1/auth/register")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isBadRequest());
    }

    @Test
    void register_controller_duplicate_returns409() throws Exception {
        // サービスが DuplicateResourceException を投げたとき、コントローラが HTTP 409 を返すことを検証する
        // Arrange: service throws DuplicateResourceException
        doThrow(new DuplicateResourceException("email exists")).when(authService).register(any(RegisterRequest.class));

        RegisterRequest req = new RegisterRequest();
        req.setUsername("dup");
        req.setEmail("dup@ginga.info");
        req.setPassword("Aa1!aaaa");

        mockMvc.perform(post("/api/v1/auth/register")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isConflict());
    }

    @Test
    void login_success_returns200() throws Exception {
        // 正しい資格情報の場合、HTTP 200 とトークンが返されることを検証する
        UserResponse ur = new UserResponse();
        ur.setId(1L);
        ur.setUsername("user");
        ur.setEmail("u@ginga.info");
        
        LoginResponse lr = new LoginResponse(ur, "dummy-token", 3600);
        
        when(authService.login(any(LoginRequest.class))).thenReturn(lr);

        LoginRequest req = new LoginRequest();
        req.setUsernameOrEmail("user");
        req.setPassword("pass");

        mockMvc.perform(post("/api/v1/auth/login")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.token").value("dummy-token"))
            .andExpect(jsonPath("$.user.username").value("user"));
    }

    @Test
    void login_fail_returns401() throws Exception {
        // 認証に失敗した場合、HTTP 401 が返されることを検証する
        doThrow(new InvalidCredentialsException("bad creds")).when(authService).login(any(LoginRequest.class));

        LoginRequest req = new LoginRequest();
        req.setUsernameOrEmail("user");
        req.setPassword("wrong");

        mockMvc.perform(post("/api/v1/auth/login")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isUnauthorized());
    }

    @org.junit.jupiter.api.Test
    void confirm_endpoint_invalidToken_returns400() throws Exception {
        // confirm エンドポイントが不正／存在しないトークンに対して HTTP 400 を返すことを検証する
        when(confirmationTokenService.findByToken("bad")).thenReturn(java.util.Optional.empty());

        mockMvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/auth/confirm")
                .param("token", "bad"))
            .andExpect(status().isBadRequest());
    }

    @org.junit.jupiter.api.Test
    void confirm_endpoint_validToken_enablesUser() throws Exception {
        // 有効なトークンが関連ユーザーを有効化し、HTTP 200 を返すことを検証する
        com.ginga.naviai.auth.entity.ConfirmationToken ct = new com.ginga.naviai.auth.entity.ConfirmationToken();
        com.ginga.naviai.auth.entity.User u = new com.ginga.naviai.auth.entity.User();
        u.setId(50L);
        u.setEnabled(false);
        ct.setUser(u);
        ct.setToken("t1");
        ct.setExpiresAt(java.time.Instant.now().plusSeconds(3600));
        when(confirmationTokenService.findByToken("t1")).thenReturn(java.util.Optional.of(ct));

        mockMvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/auth/confirm")
                .param("token", "t1"))
            .andExpect(status().isOk());
        // userRepository.save called via controller
        verify(userRepository, times(1)).save(any());
    }

    @org.junit.jupiter.api.Test
    void confirm_endpoint_expiredToken_returns400() throws Exception {
        // 期限切れトークンが HTTP 400 を返すこと（トークン期限切れ）を検証する
        com.ginga.naviai.auth.entity.ConfirmationToken ct = new com.ginga.naviai.auth.entity.ConfirmationToken();
        ct.setToken("t-exp");
        com.ginga.naviai.auth.entity.User u = new com.ginga.naviai.auth.entity.User();
        u.setId(51L);
        ct.setUser(u);
        ct.setExpiresAt(java.time.Instant.now().minusSeconds(3600));
        when(confirmationTokenService.findByToken("t-exp")).thenReturn(java.util.Optional.of(ct));

        mockMvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/auth/confirm")
                .param("token", "t-exp"))
            .andExpect(status().isBadRequest());
    }

    @org.junit.jupiter.api.Test
    void confirm_endpoint_alreadyConfirmed_returnsOk() throws Exception {
        // 既に確認済みのトークンが呼ばれた場合、冪等的に HTTP 200 を返すことを検証する
        com.ginga.naviai.auth.entity.ConfirmationToken ct = new com.ginga.naviai.auth.entity.ConfirmationToken();
        ct.setToken("t-already");
        com.ginga.naviai.auth.entity.User u = new com.ginga.naviai.auth.entity.User();
        u.setId(52L);
        u.setEnabled(false);
        ct.setUser(u);
        ct.setExpiresAt(java.time.Instant.now().plusSeconds(3600));
        ct.setConfirmedAt(java.time.Instant.now().minusSeconds(10));
        when(confirmationTokenService.findByToken("t-already")).thenReturn(java.util.Optional.of(ct));

        mockMvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/api/v1/auth/confirm")
                .param("token", "t-already"))
            .andExpect(status().isOk());
    }

    @Test
    void refresh_success_returns200() throws Exception {
        // 有効なリフレッシュトークンで新しいトークンが返されることを検証する
        TokenResponse tokenResponse = new TokenResponse("new-access-token", 3600, "new-refresh-token");
        when(authService.refreshTokens("valid-refresh-token")).thenReturn(tokenResponse);

        RefreshRequest req = new RefreshRequest("valid-refresh-token");

        mockMvc.perform(post("/api/v1/auth/refresh")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.accessToken").value("new-access-token"))
            .andExpect(jsonPath("$.refreshToken").value("new-refresh-token"))
            .andExpect(jsonPath("$.expiresIn").value(3600));
    }

    @Test
    void refresh_invalidToken_returns401() throws Exception {
        // 無効なリフレッシュトークンで HTTP 401 が返されることを検証する
        doThrow(new InvalidTokenException("Invalid refresh token"))
            .when(authService).refreshTokens("invalid-token");

        RefreshRequest req = new RefreshRequest("invalid-token");

        mockMvc.perform(post("/api/v1/auth/refresh")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isUnauthorized());
    }

    @Test
    void refresh_missingToken_returns400() throws Exception {
        // リフレッシュトークンが空の場合、バリデーションエラーで HTTP 400 が返されることを検証する
        RefreshRequest req = new RefreshRequest("");

        mockMvc.perform(post("/api/v1/auth/refresh")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isBadRequest());
    }

    // ========== ログアウト関連のテスト ==========

    @Test
    void logout_success_returns200() throws Exception {
        // ログアウトが正常に処理され HTTP 200 と成功メッセージが返されることを検証する
        doNothing().when(authService).logout(eq("testuser"), any(Optional.class), any(Optional.class));

        LogoutRequest req = new LogoutRequest("valid-refresh-token");

        mockMvc.perform(post("/api/v1/auth/logout")
                .param("username", "testuser")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.message").value("Logged out successfully"));

        verify(authService, times(1)).logout(eq("testuser"), any(Optional.class), any(Optional.class));
    }

    @Test
    void logout_withoutRefreshToken_returns200() throws Exception {
        // リフレッシュトークンなしでもログアウトが成功し HTTP 200 が返されることを検証する
        doNothing().when(authService).logout(eq("testuser"), any(Optional.class), any(Optional.class));

        mockMvc.perform(post("/api/v1/auth/logout")
                .param("username", "testuser")
                .contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.message").value("Logged out successfully"));
    }

    @Test
    void logout_invalidToken_returns401() throws Exception {
        // 無効なリフレッシュトークンの場合 HTTP 401 が返されることを検証する
        doThrow(new InvalidTokenException("Token does not belong to the user"))
            .when(authService).logout(eq("testuser"), any(Optional.class), any(Optional.class));

        LogoutRequest req = new LogoutRequest("invalid-token");

        mockMvc.perform(post("/api/v1/auth/logout")
                .param("username", "testuser")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isUnauthorized());
    }

    @Test
    void logout_missingUsername_returns400() throws Exception {
        // ユーザー名パラメータが欠落している場合 HTTP 400 が返されることを検証する
        LogoutRequest req = new LogoutRequest("some-token");

        mockMvc.perform(post("/api/v1/auth/logout")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isBadRequest());
    }

    @Test
    void logout_emptyUsername_returns400() throws Exception {
        // ユーザー名が空文字の場合 HTTP 400 が返されることを検証する
        LogoutRequest req = new LogoutRequest("some-token");

        mockMvc.perform(post("/api/v1/auth/logout")
                .param("username", "")
                .contentType(MediaType.APPLICATION_JSON)
                .content(mapper.writeValueAsString(req)))
            .andExpect(status().isBadRequest());
    }
}

